<header class="page-heading"><div><p class="eyebrow">FIND YOUR NEXT CONNECTION</p><h1>A little easier to find<span class="heading-dot">.</span></h1><p>Search your decks, subjects, questions, and answers in one place.</p></div></header>
<section class="panel"><form method="get" action="<?= e(url('/search')) ?>" class="filter-bar global-search"><div class="search-field"><?= icon('search',22) ?><label class="sr-only" for="global-query">Search your learning collection</label><input id="global-query" type="search" name="q" value="<?= e($query) ?>" maxlength="200" placeholder="A concept, a subject, a question…" autofocus></div><button class="btn btn-primary" type="submit">Search collection</button><?php if ($query !== ''): ?><a class="text-link" href="<?= e(url('/search')) ?>">Clear search</a><?php endif; ?></form><p class="field-hint">Only your own decks and flashcards appear in these results.</p></section>
<?php if ($query === ''): ?><section class="panel empty-state"><span class="empty-icon"><?= icon('search',36) ?></span><h2>What’s on your mind?</h2><p>A few words can bring an idea back into focus. Try a deck title, a subject, or something you remember from a card.</p></section>
<?php elseif (!$deckResults && !$cardResults): ?><section class="panel empty-state"><span class="empty-icon"><?= icon('search',36) ?></span><h2>No matches just yet</h2><p>We couldn't find “<?= e($query) ?>” in your collection. Try fewer words or a different way of describing the idea.</p><a href="<?= e(url('/search')) ?>" class="btn btn-secondary">Start a new search</a></section>
<?php else: ?><p class="section-caption"><?= count($deckResults) ?> decks and <?= count($cardResults) ?> flashcards found for “<?= e($query) ?>”</p>
<?php if ($deckResults): ?><section class="panel"><div class="panel-heading"><h2>Decks</h2><span class="badge"><?= count($deckResults) ?> matches</span></div><div class="deck-grid"><?php foreach ($deckResults as $deck): ?><article class="deck-card" style="--deck-color: <?= e($deck['color']) ?>"><span class="deck-color"><?= icon('decks',22) ?></span><span class="badge"><?= e($deck['subject'] ?: 'General') ?></span><h3><a href="<?= e(url('/decks/' . ((int) $deck['id']))) ?>"><?= e($deck['title']) ?></a></h3><p><?= e(excerpt($deck['description'] ?: 'Your learning collection.')) ?></p><a class="text-link" href="<?= e(url('/decks/' . ((int) $deck['id']))) ?>">Open deck <?= icon('arrow',16) ?></a></article><?php endforeach; ?></div></section><?php endif; ?>
<?php if ($cardResults): ?><section class="panel"><div class="panel-heading"><h2>Flashcards</h2><span class="badge"><?= count($cardResults) ?> matches</span></div><ol class="card-list"><?php foreach ($cardResults as $index => $card): ?><li class="flashcard-row"><span class="card-index"><?= icon('cards',21) ?></span><div class="card-copy"><span class="badge"><?= e($card['deck_title']) ?></span><h3><?= nl2br(e($card['question'])) ?></h3><p class="muted"><?= nl2br(e(excerpt($card['answer'],260))) ?></p><a class="text-link" href="<?= e(url('/decks/' . ((int) $card['deck_id']))) ?>">Open deck <?= icon('arrow',16) ?></a></div><div class="card-actions"><a href="<?= e(url('/cards/' . ((int) $card['id']) . '/edit')) ?>" class="btn btn-ghost btn-small"><?= icon('edit',17) ?> Edit</a></div></li><?php endforeach; ?></ol></section><?php endif; ?><?php endif; ?>
